// Separa los que ya vencieron. expira_en se lee del custom field.
// Si viene vacío o no parsea, se ignora: mejor no liberar que liberar de más.
const ahora = Date.now();
const oportunidades = $input.first().json.opportunities || [];
const vencidos = [];

for (const o of oportunidades) {
  const campos = o.customFields || [];
  const buscar = (clave) => {
    const c = campos.find(x => (x.fieldKey || '').endsWith(clave) || x.id === clave);
    return c ? (c.fieldValue ?? c.value) : null;
  };

  const expira = buscar('expira_en');
  const estado = buscar('estado_apartado');
  if (!expira || estado === 'pagado' || estado === 'vencido') continue;

  const t = Date.parse(expira);
  if (Number.isNaN(t)) continue;   // formato raro: no se toca
  if (t > ahora) continue;          // todavía tiene tiempo

  vencidos.push({
    opportunityId: o.id,
    contactId: o.contactId,
    sku: buscar('sku_apartado'),
    articulo: buscar('articulo_apartado'),
    cantidad: Number(buscar('cantidad_apartada') || 1),
    expira_en: expira
  });
}

return vencidos.map(v => ({ json: v }));

// Para cada vencido, encuentra su price y calcula el stock devuelto.
const productos = $input.first().json.products || [];
const vencidos = $('¿Cuáles vencieron?').all().map(i => i.json);
const salida = [];

for (const v of vencidos) {
  for (const p of productos) {
    for (const precio of (p.prices || [])) {
      if ((precio.sku || '').trim() === (v.sku || '').trim()) {
        salida.push({ json: { ...v,
          productId: p._id || p.id,
          priceId: precio._id || precio.id,
          nuevoStock: Number(precio.availableQuantity ?? 0) + v.cantidad } });
      }
    }
  }
}
return salida;
